text:
{
  "items": [
    {
      "index": 1,
      "kps": [
        "K5"
      ],
      "scene": "判断积与因数的大小关系",
      "plan": "【易错辨析】给出一个非零数分别乘以大于1、小于1和等于1的数，学生根据乘数与1的关系判断积与原数的大小，选出积最小的选项。"
    },
    {
      "index": 2,
      "kps": [
        "K3"
      ],
      "scene": "确定积的小数位数",
      "plan": "【直接应用】给出两个小数乘法算式（不计算结果），学生根据因数中小数位数的总和，判断积是几位小数，选出正确选项。"
    },
    {
      "index": 3,
      "kps": [
        "K2"
      ],
      "scene": "单位换算中的小数点移动",
      "plan": "【直接应用】给出一个以米为单位的长度，要求换算成千米或厘米，学生根据进率判断小数点移动的方向和位数，选出正确结果。"
    },
    {
      "index": 4,
      "kps": [
        "K1"
      ],
      "scene": "小数乘整数的意义理解",
      "plan": "【判断说理】陈述“0.8×5表示5个0.8相加的和”，学生结合小数乘整数的意义判断该说法是否正确。"
    },
    {
      "index": 5,
      "kps": [
        "K4"
      ],
      "scene": "小数乘法竖式计算细节",
      "plan": "【易错辨析】展示一个末尾有0的小数乘法竖式过程（如先点小数点再去0，或先去0再点小数点），学生判断处理末尾0的步骤是否规范正确。"
    },
    {
      "index": 6,
      "kps": [
        "K2"
      ],
      "scene": "根据积的变化求因数",
      "plan": "【逆向求原数】已知两个数的积，若其中一个因数扩大10倍，另一个因数缩小100倍，学生推导新积与原积的关系，求出新的积。"
    },
    {
      "index": 7,
      "kps": [
        "K3"
      ],
      "scene": "补0占位确定小数点位置",
      "plan": "【逆向求原数】给出整数乘法的结果和小数乘法中因数的总位数，但积的位数不足，学生需在前面补0并点上小数点，填写正确的小数结果。"
    },
    {
      "index": 8,
      "kps": [
        "K6"
      ],
      "scene": "利用运算律简化填空",
      "plan": "【直接应用】给出形如 $a \times b + a \times c$ 的算式，学生识别公因数，运用乘法分配律将其转化为 $a \times (b+c)$ 的形式，填写括号内的数。"
    },
    {
      "index": 9,
      "kps": [
        "K5"
      ],
      "scene": "比较大小不计算",
      "plan": "【比较择优】给出两组小数乘法算式，其中一组乘数大于1，另一组小于1，学生不计算具体数值，直接根据乘数特征在横线上填入大于、小于或等于号。"
    },
    {
      "index": 10,
      "kps": [
        "K1"
      ],
      "scene": "小数乘整数竖式计算",
      "plan": "【直接应用】列出一个两位小数乘一位整数的竖式结构，学生按整数乘法计算后，根据因数的小数位数从右边起数出相应位数点上小数点。"
    },
    {
      "index": 11,
      "kps": [
        "K4"
      ],
      "scene": "小数乘小数竖式计算",
      "plan": "【直接应用】列出一个两位小数乘两位小数的竖式结构（积的末尾有0），学生先按整数乘法算出积，再点小数点，最后去掉小数末尾的0。"
    },
    {
      "index": 12,
      "kps": [
        "K6",
        "K4"
      ],
      "scene": "小数乘法简便运算",
      "plan": "【多步综合】给出形如 $1.25 \times 3.2 \times 0.25$ 的算式，学生先将3.2拆分为 $0.8 \times 4$，再利用乘法结合律分别与1.25和0.25相乘，最后求出结果。"
    },
    {
      "index": 13,
      "kps": [
        "K1",
        "K2"
      ],
      "scene": "购买文具计算总价",
      "plan": "【多步综合】已知每支钢笔的价格（小数）和购买数量（整数），学生先列出小数乘整数算式求出总价，若涉及单位换算（如角转元），再移动小数点得出最终金额。"
    },
    {
      "index": 14,
      "kps": [
        "K4",
        "K3"
      ],
      "scene": "长方形花坛铺草坪面积",
      "plan": "【多步综合】给出长方形花坛的长和宽（均为小数），学生先根据长乘宽计算面积（注意积的小数位数及末尾去0），再根据每平方米草皮价格计算总费用。"
    },
    {
      "index": 15,
      "kps": [
        "K6",
        "K1"
      ],
      "scene": "超市购物凑单优惠",
      "plan": "【比较择优】给出两种购买方案：方案A是单件购买累加，方案B是利用乘法分配律结构的组合购买（如买5套书），学生分别计算或简便运算后，比较哪种方案更省钱。"
    },
    {
      "index": 16,
      "kps": [
        "K2",
        "K5"
      ],
      "scene": "汽车行驶路程估算",
      "plan": "【估算与检验】已知汽车速度和行驶时间（小数），学生先根据速度与时间的关系列式，利用乘数与1的关系估算积的范围，再通过小数点移动规律精确计算行驶路程。"
    }
  ]
}
